ALTER TABLE "spideryarn"."citation_finds" ADD CONSTRAINT "citation_finds_lookup_state" CHECK ("spideryarn"."citation_finds"."lookup_state" is null or "spideryarn"."citation_finds"."lookup_state" in ('assessed', 'no-extract', 'not-identified', 'unreadable'));--> statement-breakpoint
